Dictionary<string, bool> raw = LoadFeatureFlagsFromRedis();
FrozenDictionary<string, bool> flags = raw.ToFrozenDictionary(
    StringComparer.OrdinalIgnoreCase);

// Inject flags into DI — every request reads without locking
bool enabled = flags.TryGetValue("new-checkout", out bool on) && on;

ImmutableDictionary<string, int> v1 = ImmutableDictionary<string, int>.Empty;
v1 = v1.Add("tenant-a", 42);

// v1 is still safe for readers holding the old reference
ImmutableDictionary<string, int> v2 = v1.SetItem("tenant-b", 7);

Console.WriteLine(v1.Count); // 1 — unchanged
Console.WriteLine(v2.Count); // 2 — new snapshot

ImmutableArray<string> scopes = ["exam.read", "exam.write"];

void CheckScopes(ImmutableArray<string> allowed)
{
    // Passed by value (struct) — no heap allocation for the wrapper
    foreach (string scope in allowed)
        Validate(scope);
}

